_choice_fnm_alias() {
    _helper_fnm_alias_names
}

_choice_fnm_installed_version() {
    _helper_fnm_installed_versions
}

_choice_fnm_lts() {
    _argc_util_cache 3600 _helper_fnm_lts_names fnm-lts-names
}

_choice_fnm_remote_version() {
    _argc_util_cache 3600 _helper_fnm_remote_versions fnm-remote-versions
}

_choice_fnm_using() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
    else
        _helper_fnm_installed_versions
    fi
}

_helper_fnm_alias_names() {
    fnm list 2>/dev/null | _argc_util_strip_ansi | gawk '
        {
            sub(/^[ \t]*\*[ \t]*/, "")
            for (i = 2; i <= NF; i++) {
                gsub(/,/, "", $i)
                if ($i != "") print $i
            }
        }'
}

_helper_fnm_installed_versions() {
    fnm list 2>/dev/null | _argc_util_strip_ansi | gawk '
        {
            sub(/^[ \t]*\*[ \t]*/, "")
            if (NF == 0) next
            print $1
            for (i = 2; i <= NF; i++) {
                gsub(/,/, "", $i)
                if ($i != "") print $i
            }
        }'
}

_helper_fnm_lts_names() {
    fnm ls-remote --lts 2>/dev/null | _argc_util_strip_ansi | gawk '
        match($0, /\([^)]*\)/) {
            name = substr($0, RSTART + 1, RLENGTH - 2)
            if (name != "") print name
        }'
}

_helper_fnm_remote_versions() {
    fnm ls-remote 2>/dev/null | _argc_util_strip_ansi | gawk 'NF { print $1 }'
}
